@pragma('vm:entry-point')
double barcodeWeightedRatio(String digits) {
  if (digits.isEmpty) return 0.0;
  int sum = 0;
  bool oddPosition = true;
  for (int i = 0; i < digits.length; i++) {
    int d = digits.codeUnitAt(i) - 48;
    sum += oddPosition ? d : d * 3;
    oddPosition = !oddPosition;
  }
  return sum / digits.length;
}

@pragma('vm:entry-point')
void main() {
  assert(barcodeWeightedRatio('1234') == 5.5);
  assert(barcodeWeightedRatio('1') == 1.0);
  assert(barcodeWeightedRatio('123456') == 7.5);
  print('All tests passed!');
}

tests:
