  final candidate = barcodeWeightedRatio;

  expect(candidate(''), 0.0);
  expect(candidate('1'), 1.0);
  expect(candidate('12'), 3.5);
  expect(candidate('11'), 2.0);
  expect(candidate('21'), 2.5);
  expect(candidate('1234'), 5.5);
  expect(candidate('123456'), 7.5);
  expect(candidate('999'), 15.0);
  expect(candidate('0000'), 0.0);
}

