bool isModuleCountInWindow(int version, int minDayIndex, int maxDayIndex) {
  if (version < 1 || version > 40) return false;
  if (minDayIndex > maxDayIndex) return false;
  final side = 17 + 4 * version;
  final totalModules = side * side;
  return totalModules >= minDayIndex && totalModules <= maxDayIndex;
}

