@pragma('vm:entry-point')
List<String> sortAsciiRowsByAlignment(List<String> rows) {
  List<String> result = List<String>.from(rows);
  result.sort((String a, String b) {
    int leftA = a.length;
    int rightA = -1;
    for (int i = 0; i < a.length; i++) {
      if (a[i] != ' ') {
        if (leftA == a.length) leftA = i;
        rightA = i;
      }
    }
    int spanA = (rightA == -1) ? 0 : rightA - leftA + 1;
    int leftB = b.length;
    int rightB = -1;
    for (int i = 0; i < b.length; i++) {
      if (b[i] != ' ') {
        if (leftB == b.length) leftB = i;
        rightB = i;
      }
    }
    int spanB = (rightB == -1) ? 0 : rightB - leftB + 1;
    if (leftA != leftB) return leftA.compareTo(leftB);
    if (spanA != spanB) return spanB.compareTo(spanA);
    return a.compareTo(b);
  });
  return result;
}

@pragma('vm:entry-point')
void main() {
  assert(sortAsciiRowsByAlignment(["  hello", "hello", "   hi"]).first == "hello");
  assert(sortAsciiRowsByAlignment([]).length == 0);
  assert(sortAsciiRowsByAlignment(["z", "a"]).first == "a");
  print('All tests passed!');
}

