@pragma('vm:entry-point')
int calculateLedgerBalance(List<String> entries) {
  return entries.fold(0, (int balance, String entry) {
    if (entry.length < 2) return balance;
    String type = entry[0];
    int amount = int.tryParse(entry.substring(1)) ?? 0;
    if (amount < 0) return balance;
    if (type == 'D') {
      return balance + amount;
    } else if (type == 'W') {
      return balance >= amount ? balance - amount : balance;
    } else if (type == 'T') {
      return balance >= amount ? balance - amount : balance - 5;
    } else if (type == 'F') {
      return balance - amount;
    }
    return balance;
  });
}

@pragma('vm:entry-point')
void main() {
  assert(calculateLedgerBalance(['D100', 'W50', 'W60', 'T20', 'F10', 'T150']) == 15);
  assert(calculateLedgerBalance([]) == 0);
  assert(calculateLedgerBalance(['T10']) == -5);
  print('All tests passed!');
}

