double calculateMorseWeight(List<String> morseWords) {
  return morseWords
      .expand<String>((String word) => word.split(''))
      .fold<double>(0.0, (double sum, String char) {
        if (char == '-') {
          return sum + 1.0;
        } else if (char == '.') {
          return sum + 0.5;
        }
        return sum;
      });
