  final candidate = sortByKingDistance;

  expect(candidate(<int>[], 0), <int>[]);
  expect(candidate([15], 0), <int>[15]);
  expect(candidate([36, 19, 28], 27), <int>[19, 28, 36]);
  expect(candidate([9, 1, 8], 0), <int>[1, 8, 9]);
  expect(candidate([0, 35, 63], 35), <int>[35, 0, 63]);
  expect(candidate([54, 45, 63], 63), <int>[63, 54, 45]);
  expect(candidate([63, 56, 7, 0], 27), <int>[0, 7, 56, 63]);
  expect(candidate([18, 17, 26, 25], 27), <int>[26, 18, 25, 17]);
  expect(candidate([35, 36, 37, 27, 28, 29], 28), <int>[28, 27, 29, 36, 35, 37]);
