List<String> sortByRoundedQuarters(List<double> amounts) {
  List<String> formatted = amounts.map((a) => a.toStringAsFixed(2)).toList();
  formatted.sort((String a, String b) {
    double da = double.parse(a);
    double db = double.parse(b);
    double ra = (da * 4).round() / 4.0;
    double rb = (db * 4).round() / 4.0;
    return ra.compareTo(rb);
  });
  return formatted;
}

