@pragma('vm:entry-point')
bool mazeCellsHaveEvenOpenings(List<int> cellMasks) {
  const int directionBits = 0xF;
  for (final cell in cellMasks) {
    int openings = cell & directionBits;
    openings ^= openings >> 2;
    openings ^= openings >> 1;
    if ((openings & 1) == 1) {
      return false;
    }
  }
  return true;
}

@pragma('vm:entry-point')
void main() {
  assert(mazeCellsHaveEvenOpenings([3, 12, 0]) == true);
  assert(mazeCellsHaveEvenOpenings([3, 7]) == false);
  assert(mazeCellsHaveEvenOpenings([]) == true);
  print('All tests passed!');
}

tests:
void main() {
  final candidate = mazeCellsHaveEvenOpenings;

  expect(candidate([]), true);
  expect(candidate([0]), true);
  expect(candidate([1]), false);
  expect(candidate([15]), true);
  expect(candidate([3, 5, 10, 12]), true);
  expect(candidate([6, 8]), false);
  expect(candidate([16, 19]), true);
