Set<int> synchronizedPlaylistDropDays(List<int> playlistA, List<int> playlistB, int startDayA, int startDayB, int fromDay, int toDay) {
  if (fromDay > toDay || playlistA.isEmpty || playlistB.isEmpty) return <int>{};
  final List<int> offsetsA = <int>[], offsetsB = <int>[];
  int cycleA = 0, cycleB = 0;
  for (final int d in playlistA) {
    if (d <= 0) return <int>{};
    offsetsA.add(cycleA); cycleA += d;
  }
  for (final int d in playlistB) {
    if (d <= 0) return <int>{};
    offsetsB.add(cycleB); cycleB += d;
  }
  int gcd(int a, int b) {
    a = a.abs(); b = b.abs();
    while (b != 0) { final int t = a % b; a = b; b = t; }
    return a;
  }
  int inverse(int a, int m) {
    int oldR = a % m, r = m, oldS = 1, s = 0;
    while (r != 0) {
      final int q = oldR ~/ r;
      final int nr = oldR - q * r; oldR = r; r = nr;
      final int ns = oldS - q * s; oldS = s; s = ns;
    }
    return oldS % m;
  }
  final Set<int> days = <int>{};
  for (final int oa in offsetsA) {
    final int ra = (startDayA + oa) % cycleA;
    for (final int ob in offsetsB) {
      final int rb = (startDayB + ob) % cycleB;
      final int g = gcd(cycleA, cycleB), diff = rb - ra;
      if (diff % g != 0) continue;
      final int m1 = cycleA ~/ g, m2 = cycleB ~/ g;
      final int t = m2 == 1 ? 0 : ((diff ~/ g) * inverse(m1, m2)) % m2;
      final int period = cycleA * m2;
      int day = (ra + cycleA * t) % period;
      if (day < fromDay) { day += ((fromDay - day + period - 1) ~/ period) * period; } else { day -= ((day - fromDay) ~/ period) * period; }
      while (day <= toDay) { days.add(day); day += period; }
    }
  }
  return days;
}

