String findFirstLogAtOrAfter(List<String> logs, int targetTimestamp) {
  int left = 0;
  int right = logs.length;
  while (left < right) {
    int mid = left + (right - left) ~/ 2;
    int timestamp = int.parse(logs[mid].split(' ')[0]);
    if (timestamp < targetTimestamp) {
      left = mid + 1;
    } else {
      right = mid;
    }
  }
  if (left < logs.length) {
    return logs[left];
  } else {
    return 'NOT_FOUND';
  }
}

