String findExactPacketWindow(List<int> packetSizes, int targetSize) {
  int start = 0;
  int currentSum = 0;
  for (int end = 0; end < packetSizes.length; end++) {
    currentSum += packetSizes[end];
    while (currentSum > targetSize && start <= end) {
      currentSum -= packetSizes[start];
      start++;
    }
    if (currentSum == targetSize) {
      return '$start-$end';
    }
  }
  return 'none';
}

