@pragma('vm:entry-point')
int calculateQrModuleComplexity(List<List<bool>> modules) {
  if (modules.isEmpty) return 0;
  final height = modules.length;
  final width = modules[0].length;
  if (height < 2 || width < 2) return 0;

  // Step 1: Map each non-overlapping 2x2 block to a 4-bit pattern ID (0-15).
  final patternIds = <int>[];
  for (int r = 0; r < height - 1; r += 2) {
    for (int c = 0; c < width - 1; c += 2) {
      int id = 0;
      if (modules[r][c]) id |= 8;         // top-left
      if (modules[r][c + 1]) id |= 4;     // top-right
      if (modules[r + 1][c]) id |= 2;     // bottom-left
      if (modules[r + 1][c + 1]) id |= 1; // bottom-right
      patternIds.add(id);
    }
  }

  // Step 2: Partition pattern IDs by parity of dark-module count (even/odd).
  final evenParity = <int>[];
  final oddParity = <int>[];
  for (int id in patternIds) {
    int count = 0;
    int v = id;
    while (v > 0) {
      count += v & 1;
      v >>= 1;
    }
    if (count % 2 == 0) {
      evenParity.add(id);
    } else {
      oddParity.add(id);
    }
  }

  // Step 3: Dedupe each partition.
  final uniqueEven = evenParity.toSet();
  final uniqueOdd = oddParity.toSet();

  // Step 4: Fold to compute difference (unique even patterns minus unique odd patterns).
  return [uniqueEven, uniqueOdd].fold(0, (acc, set) => acc + (set == uniqueEven ? set.length : -set.length));
}

@pragma('vm:entry-point')
void main() {
  assert(calculateQrModuleComplexity([]) == 0);
  assert(calculateQrModuleComplexity([[false, false], [false, false]]) == 1);
  assert(calculateQrModuleComplexity([[true, false], [false, false]]) == -1);
  print('All tests passed!');
}

