int countWifiSignalBinDays(List<int> signalDaily, int startDay, int endDay, int bin) {
  if (startDay > endDay) return 0;
  int count = 0;
  int len = signalDaily.length;
  for (int i = startDay; i <= endDay && i < len; i++) {
    int sig = signalDaily[i];
    bool qualifies = false;
    if (bin == 1) {
      qualifies = sig >= -50;
    } else if (bin == 2) {
      qualifies = sig < -50 && sig >= -70;
    } else if (bin == 3) {
      qualifies = sig < -70 && sig >= -80;
    } else if (bin == 4) {
      qualifies = sig < -80;
    }
    if (qualifies) count++;
  }
  return count;
}

