@pragma('vm:entry-point')
String diceTournamentWinner(List<int> startOffsets, List<int> multipliers, int winningScore) {
  int n = startOffsets.length;
  if (n == 0) return "No players.";
  List<int> scores = List.filled(n, 0);
  int day = 0;
  while (true) {
    int diceRoll = (day % 6) + 1;
    for (int i = 0; i < n; i++) {
      if (day >= startOffsets[i]) {
        scores[i] += diceRoll * multipliers[i];
      }
    }
    int maxScore = -1;
    for (int s in scores) {
      if (s > maxScore) maxScore = s;
    }
    if (maxScore >= winningScore) {
      for (int i = 0; i < n; i++) {
        if (scores[i] == maxScore) {
          return "Player $i wins on day $day with $maxScore points.";
        }
      }
    }
    day++;
  }
}

@pragma('vm:entry-point')
void main() {
  assert(diceTournamentWinner([0,2], [2,3], 30) == "Player 1 wins on day 4 with 36 points.");
  assert(diceTournamentWinner([0], [5], 10) == "Player 0 wins on day 1 with 15 points.");
  assert(diceTournamentWinner([], [], 5) == "No players.");
