bool isBalancedAfterRemovingPattern(String dna, String pattern) {
  String cleaned;
  if (pattern.isEmpty) {
    cleaned = dna;
  } else {
    StringBuffer buffer = StringBuffer();
    int i = 0;
    while (i < dna.length) {
      if (i + pattern.length <= dna.length && dna.substring(i, i + pattern.length) == pattern) {
        i += pattern.length;
      } else {
        buffer.write(dna[i]);
        i++;
      }
    }
    cleaned = buffer.toString();
  }
  int purines = 0;
  int pyrimidines = 0;
  for (int j = 0; j < cleaned.length; j++) {
    String c = cleaned[j];
    if (c == 'A' || c == 'G') {
      purines++;
    } else if (c == 'C' || c == 'T') {
      pyrimidines++;
    }
  }
  return purines == pyrimidines;
}

