Map<String, int> serverLogTimeoutStats(List<int> sortedLogDurations, int timeoutMs) {
  int left = 0, right = sortedLogDurations.length;
  while (left < right) {
    final mid = left + (right - left) ~/ 2;
    if (sortedLogDurations[mid] <= timeoutMs) left = mid + 1;
    else right = mid;
  }
  return {
    'firstTimeoutIndex': left < sortedLogDurations.length ? left : -1,
    'timeoutCount': sortedLogDurations.length - left,
  };
}

