List<int> parseMazeGridOpenings(String gridSpec) {
  final result = <int>[];
  if (gridSpec.isEmpty) return result;
  for (final row in gridSpec.split(';')) {
    if (row.isEmpty) continue;
    for (final cell in row.split('|')) {
      var count = 0;
      var mask = 0;
      for (var i = 0; i < cell.length; i++) {
        final ch = cell[i];
        var bit = 0;
        if (ch == 'N') bit = 1;
        else if (ch == 'E') bit = 2;
        else if (ch == 'S') bit = 4;
        else if (ch == 'W') bit = 8;
        if (bit != 0 && (mask & bit) == 0) {
          mask |= bit;
          count++;
        }
      }
      result.add(count);
    }
  }
  return result;
}

@pragma('vm:entry-point')
void main() {
  assert(parseMazeGridOpenings("N|E;S|W").toString() == "[1, 1, 1, 1]");
  assert(parseMazeGridOpenings("").toString() == "[]");
  assert(parseMazeGridOpenings("NESW").toString() == "[4]");
  print('All tests passed!');
}

tests:
void main() {
  final candidate = parseMazeGridOpenings;

  expect(candidate(""), []);
  expect(candidate("NESW"), [4]);
  expect(candidate("N|E|NS;W|EW|"), [1, 1, 2, 1, 2, 0]);
  expect(candidate("NxE|S2W"), [2, 2]);
  expect(candidate("NEN|WW"), [2, 1]);
  expect(candidate("|N|"), [0, 1, 0]);
  expect(candidate(";;"), []);
  expect(candidate("N;E;S;W"), [1, 1, 1, 1]);
}

