@pragma('vm:entry-point')
double computeLogCohesionScore(List<String> logLines) {
  if (logLines.isEmpty) return 0.0;
  int orMask = 0;
  int andMask = 0xFFFFFFFF;
  int popcount(int x) {
    x &= 0xFFFFFFFF;
    x = x - ((x >> 1) & 0x55555555);
    x = (x & 0x33333333) + ((x >> 2) & 0x33333333);
    x = (x + (x >> 4)) & 0x0F0F0F0F;
    x = x + (x >> 8);
    x = x + (x >> 16);
    return x & 0x3F;
  }
  for (int i = 0; i < logLines.length; i++) {
    String line = logLines[i];
    int spaceIdx = line.lastIndexOf(' ');
    String token = spaceIdx >= 0 ? line.substring(spaceIdx + 1) : line;
    if (token.startsWith('0x') || token.startsWith('0X')) {
      token = token.substring(2);
    }
    int mask;
    try {
      mask = int.parse(token, radix: 16);
    } catch (_) {
      mask = 0;
    }
    mask &= 0xFFFFFFFF;
    int shift = (i * 7) & 31;
    int rotated;
    if (shift == 0) {
      rotated = mask;
    } else {
      rotated = ((mask << shift) | (mask >> (32 - shift))) & 0xFFFFFFFF;
    }
    orMask |= rotated;
    andMask &= rotated;
  }
  int shared = popcount(andMask);
  int uncommon = popcount(orMask & (~andMask & 0xFFFFFFFF));
  return shared.toDouble() * 0.5 + uncommon.toDouble() * 0.25;
}

@pragma('vm:entry-point')
void main() {
  assert(computeLogCohesionScore([]) == 0.0);
  assert(computeLogCohesionScore(["FATAL 0xFFFFFFFF"]) == 16.0);
  assert(computeLogCohesionScore(["E 0x00000001", "E 0x00000001"]) == 0.5);
  print('All tests passed!');
}

tests:
void main() {
  final candidate = computeLogCohesionScore;

  expect(candidate([]), 0.0);
  expect(candidate(["FATAL 0xFFFFFFFF"]), 16.0);
  expect(candidate(["S 0xAAAAAAAA", "S 0x55555555"]), 8.0);
  expect(candidate(["M 0XFF", "M 0xFF"]), 4.0);
  expect(candidate(["E 0x00000001", "E 0x00000001"]), 0.5);
  expect(candidate(["OK", "FAIL 0x0F", "INFO 0xF0", "BAD hex"]), 2.0);
  expect(candidate(["P 0x00000003", "Q 0x00000007"]), 1.25);
}

