@pragma('vm:entry-point')
bool validateTrafficLightSequence(List<String> phases, List<int> durations) {
  if (phases.length != durations.length) return false;
  if (phases.isEmpty) return false;
  if (phases[0] != 'R') return false;

  const minDur = {
    'R': 30,
    'RY': 2,
    'G': 20,
    'Y': 3,
  };
  const maxDur = {
    'R': 120,
    'RY': 5,
    'G': 90,
    'Y': 6,
  };
  const next = {
    'R': 'RY',
    'RY': 'G',
    'G': 'Y',
    'Y': 'R',
  };

  for (int i = 0; i < phases.length; i++) {
    final p = phases[i];
    if (!minDur.containsKey(p)) return false;
    if (durations[i] < minDur[p]! || durations[i] > maxDur[p]!) return false;
    if (i > 0 && next[phases[i - 1]] != p) return false;
  }

  return true;
}

@pragma('vm:entry-point')
void main() {
  assert(validateTrafficLightSequence(["R", "RY", "G", "Y", "R"], [30, 2, 20, 3, 30]) == true);
  assert(validateTrafficLightSequence(["G", "Y"], [20, 3]) == false);
  assert(validateTrafficLightSequence(["R", "RY", "G"], [30, 2, 19]) == false);
  print('All tests passed!');
}

tests:
