  expect(candidate(["R","RY","G","Y"], [120, 5, 90, 6]), true);
  expect(candidate(["R","RY","G"], [30, 2, 19]), false);
  expect(candidate(["R","RY","G","Y"], [30, 2, 20, 7]), false);
  expect(candidate(["R","G"], [30, 20]), false);
  expect(candidate(["R"], [30, 2]), false);
