@pragma('vm:entry-point')
Map<String, int> evaluateInventoryLog(List<String> log) {
  final stack = <Map<String, int>>[<String, int>{}];

  for (final entry in log) {
    final parts = entry.split(' ');
    if (parts.length == 3) {
      final item = parts[1];
      final delta = int.tryParse(parts[2]);
      if (delta == null) continue;

      final current = stack.last;
      if (parts[0] == 'loot') {
        current[item] = (current[item] ?? 0) + delta;
      } else if (parts[0] == 'use') {
        current[item] = (current[item] ?? 0) - delta;
      }
    } else if (parts.length == 1) {
      final cmd = parts[0];
      if (cmd == 'begin') {
        stack.add(<String, int>{});
      } else if (cmd == 'commit' && stack.length > 1) {
        final popped = stack.removeLast();
        final target = stack.last;
        for (final e in popped.entries) {
          target[e.key] = (target[e.key] ?? 0) + e.value;
        }
      } else if (cmd == 'cancel' && stack.length > 1) {
        stack.removeLast();
      }
    }
  }

  while (stack.length > 1) {
    stack.removeLast();
  }

  return stack.isEmpty ? <String, int>{} : stack.first;
}

@pragma('vm:entry-point')
void main() {
  assert(evaluateInventoryLog(['loot coin 5', 'use coin 2']).toString() == '{coin: 3}');
  assert(evaluateInventoryLog([]).toString() == '{}');
  assert(evaluateInventoryLog(['begin', 'loot potion 1', 'cancel']).toString() == '{}');
  print('All tests passed!');
}

tests:
void main() {
  final candidate = evaluateInventoryLog;

  expect(candidate([]), <String, int>{});
  expect(candidate(['loot gold 10', 'use gold 3']), {'gold': 7});
  expect(candidate(['loot iron 2', 'begin', 'loot iron 3', 'commit']), {'iron': 5});
  expect(candidate(['loot iron 2', 'begin', 'loot iron 3', 'cancel']), {'iron': 2});
  expect(candidate(['loot wood 1', 'commit']), {'wood': 1});
  expect(candidate(['loot wood 1', 'begin', 'loot wood 2']), {'wood': 1});
  expect(candidate(['loot a 5', 'begin', 'loot b 1', 'begin', 'use a 2', 'cancel', 'commit']), {'a': 5, 'b': 1});
  expect(candidate(['loot gem 3', 'begin', 'use gem 3', 'commit']), {'gem': 0});
  expect(candidate(['loot gem 2', 'forge gem 1', 'use gem 1']), {'gem': 1});
