  expect(candidate('RRRAGGGGYY'), [0, 0, 0, 0, 0]);
  expect(candidate('RRRRAGGGGYYYY'), [1, 0, 0, 2, 29793]);
  expect(candidate('YRRR'), [-1, 0, 65505]);
