String expandMazeRunLength(String encoded) {
  String result = '';
  int i = 0;
  while (i < encoded.length) {
    String cellType = encoded[i];
    i++;
    int count = int.parse(encoded[i]);
    i++;
    for (int j = 0; j < count; j++) {
      if (result.isNotEmpty) result += ',';
      result += cellType;
    }
  }
  return result;
}

