  assert(analyzePasswordGeometry([[0,0], [1,1], [2,2], [3,3]], []).toString() == '{totalManhattan: 6, bboxArea: 9, pointsInExclusion: 0, maxSegmentManhattan: 2, turnCount: 0}');
