void main() {
  assert(parseRgbStream('R120G45B200').toString() == '{r: 120, g: 45, b: 200, pixels: 0, inversions: 0}');
  assert(parseRgbStream('!!!')['pixels'] == 3);
  assert(parseRgbStream('R300')['r'] == 255);
  print('All tests passed!');
}

