@pragma('vm:entry-point')
List<String> findSharedMetaItems(List<List<String>> inventories, int minPlayers) {
  if (inventories.isEmpty) return [];
  final Map<String, int> totalFrequency = {};
  final Map<String, Set<int>> inventoryPresence = {};
  for (int i = 0; i < inventories.length; i++) {
    for (final String item in inventories[i]) {
      totalFrequency[item] = (totalFrequency[item] ?? 0) + 1;
      if (!inventoryPresence.containsKey(item)) {
        inventoryPresence[item] = {};
      }
      inventoryPresence[item]!.add(i);
    }
  }
  final List<String> result = [];
  for (final MapEntry<String, Set<int>> entry in inventoryPresence.entries) {
    if (entry.value.length >= minPlayers) {
      result.add(entry.key);
    }
  }
  result.sort((String a, String b) {
    final int countA = totalFrequency[a]!;
    final int countB = totalFrequency[b]!;
    if (countA != countB) {
      return countB.compareTo(countA);
    }
    return a.compareTo(b);
  });
  return result;
}

