@pragma('vm:entry-point')
String zigzagDnaCompress(List<String> grid) {
  if (grid.isEmpty || grid[0].isEmpty) return '';
  StringBuffer seq = StringBuffer();
  for (int i = 0; i < grid.length; i++) {
    if (i % 2 == 0) {
      for (int j = 0; j < grid[i].length; j++) {
        seq.write(_dnaComplement(grid[i][j]));
      }
    } else {
      for (int j = grid[i].length - 1; j >= 0; j--) {
        seq.write(_dnaComplement(grid[i][j]));
      }
    }
  }

  String s = seq.toString();
  StringBuffer rle = StringBuffer();
  int count = 1;
  for (int i = 1; i < s.length; i++) {
    if (s[i] == s[i - 1]) {
      count++;
    } else {
      rle.write('$count${s[i - 1]}');
      count = 1;
    }
  }
  rle.write('$count${s[s.length - 1]}');
  return rle.toString();
}

String _dnaComplement(String c) {
  switch (c) {
    case 'A': return 'T';
    case 'T': return 'A';
    case 'C': return 'G';
    case 'G': return 'C';
    default: return c;
  }
}

