@pragma('vm:entry-point')
bool isValidTournamentBracket(List<String> matches) {
  if (matches.isEmpty) return true;
  final Set<String> teams = {};
  final Map<String, int> losses = {};
  for (final match in matches) {
    final idx = match.indexOf('>');
    if (idx <= 0 || idx == match.length - 1) return false;
    final winner = match.substring(0, idx);
    final loser = match.substring(idx + 1);
    if (winner == loser) return false;
    teams.add(winner);
    teams.add(loser);
    losses[loser] = (losses[loser] ?? 0) + 1;
  }
  if (matches.length != teams.length - 1) return false;
  int zeroLoss = 0, oneLoss = 0;
  for (final team in teams) {
    final count = losses[team] ?? 0;
    if (count == 0) {
      zeroLoss++;
    } else if (count == 1) {
      oneLoss++;
    } else {
      return false;
    }
  }
  return zeroLoss == 1 && oneLoss == teams.length - 1;
}

@pragma('vm:entry-point')
