@pragma('vm:entry-point')
int calculateFinalTelemetrySum(List<int> telemetryStream) {
  List<int> stack = [];
  for (int event in telemetryStream) {
    if (event > 0) {
      stack.add(event);
    } else if (event == -1) {
      if (stack.isNotEmpty) {
        stack.removeLast();
      }
    } else if (event == -2) {
      if (stack.length >= 2) {
        int a = stack.removeLast();
        int b = stack.removeLast();
        stack.add(a + b);
      }
    } else if (event == -3) {
      if (stack.isNotEmpty) {
        int sum = 0;
        while (stack.isNotEmpty) {
          sum += stack.removeLast();
        }
        stack.add(sum);
      }
    }
  }
  int total = 0;
  for (int value in stack) {
    total += value;
  }
  return total;
}

