List<int> encodePassWindows(String observations) {
  if (observations.isEmpty) return [];
  int startState = observations[0] == 'V' ? 1 : 0;
  List<int> result = [startState];
  int count = 1;
  for (int i = 1; i < observations.length; i++) {
    if (observations[i] == observations[i - 1]) {
