Map<String, int> longestBalancedVoteWindow(List<String> votes, int maxCandidates) {
  if (votes.isEmpty || maxCandidates <= 0) {
    return <String, int>{};
  }

  Map<String, int> windowCounts = <String, int>{};
  int left = 0;
  int bestLeft = 0;
  int bestLen = 0;

  for (int right = 0; right < votes.length; right++) {
    String candidate = votes[right];
    windowCounts[candidate] = (windowCounts[candidate] ?? 0) + 1;

    while (windowCounts.length > maxCandidates) {
      String leftCandidate = votes[left];
      windowCounts[leftCandidate] = windowCounts[leftCandidate]! - 1;
      if (windowCounts[leftCandidate] == 0) {
        windowCounts.remove(leftCandidate);
      }
      left++;
    }

    int windowLen = right - left + 1;
    if (windowLen > bestLen) {
      bestLen = windowLen;
      bestLeft = left;
    }
  }

  Map<String, int> result = <String, int>{};
  for (int i = bestLeft; i < bestLeft + bestLen; i++) {
    String candidate = votes[i];
    result[candidate] = (result[candidate] ?? 0) + 1;
  }

  return result;
}

