String shiftDiceRolls(String rolls, int shift) {
  int normalizedShift = ((shift % 6) + 6) % 6;
  StringBuffer result = StringBuffer();
  for (int i = 0; i < rolls.length; i++) {
    int face = int.parse(rolls[i]);
    int shifted = ((face - 1 + normalizedShift) % 6) + 1;
    result.write(shifted.toString());
  }
  return result.toString();
}

