bool hasUniformRowDensity(List<List<int>> darkModules) {
  Map<int, int> rowDensity = {};
  for (List<int> module in darkModules) {
    int row = module[0];
    rowDensity[row] = (rowDensity[row] ?? 0) + 1;
  }
  if (rowDensity.length < 2) return false;
  Map<int, int> densityFrequency = {};
  for (int count in rowDensity.values) {
    densityFrequency[count] = (densityFrequency[count] ?? 0) + 1;
  }
  List<int> distinctDensities = densityFrequency.keys.toList();
  if (distinctDensities.length > 2) return false;
  if (distinctDensities.length == 1) return true;
  distinctDensities.sort();
  return (distinctDensities[1] - distinctDensities[0]) <= 1;
}

