@pragma('vm:entry-point')
double ledgerWaveVolatility(List<List<double>> entries) {
  if (entries.isEmpty || entries[0].isEmpty) {
    return 0.0;
  }
  int rows = entries.length;
  int cols = entries[0].length;
  if (rows == 1 && cols == 1) {
    return 0.0;
  }
  double total = 0.0;
  double prev = entries[0][0];
  for (int i = 0; i < rows; i++) {
    if (i % 2 == 0) {
      for (int j = 0; j < cols; j++) {
        if (i == 0 && j == 0) continue;
        total += (entries[i][j] - prev).abs();
        prev = entries[i][j];
      }
    } else {
      for (int j = cols - 1; j >= 0; j--) {
        total += (entries[i][j] - prev).abs();
        prev = entries[i][j];
      }
    }
  }
  return total;
}

