int countDryCellsAtIntervalEndpoints(List<List<int>> grid, List<List<int>> rains, int startDay, int endDay, int threshold) {
  if (grid.isEmpty) return 0;
  int count = 0;
  for (int r = 0; r < grid.length; r++) {
    int rainByStart = 0;
    int rainByEnd = 0;
    for (int i = 0; i < rains.length; i++) {
      if (rains[i][1] == r) {
        if (rains[i][0] <= startDay) rainByStart += rains[i][2];
        if (rains[i][0] <= endDay) rainByEnd += rains[i][2];
      }
    }
    for (int c = 0; c < grid[r].length; c++) {
      int moistureStart = grid[r][c] - startDay + rainByStart;
      int moistureEnd = grid[r][c] - endDay + rainByEnd;
      if (moistureStart <= threshold || moistureEnd <= threshold) {
        count++;
      }
    }
  }
  return count;
}

