bool hasUniformMorseFrequency(List<String> symbols) {
  if (symbols.isEmpty) return true;
  Map<int, Map<String, int>> lengthGroups = {};
  for (String symbol in symbols) {
    int len = symbol.length;
    lengthGroups.putIfAbsent(len, () => {});
    lengthGroups[len]![symbol] = (lengthGroups[len]![symbol] ?? 0) + 1;
  }
  for (Map<String, int> group in lengthGroups.values) {
    if (group.length <= 1) continue;
    int? firstCount;
    for (int count in group.values) {
      if (firstCount == null) {
        firstCount = count;
      } else if (count != firstCount) {
        return false;
      }
    }
  }
  return true;
}

