List<int> qrTimingDarkModulesInRange(int version, int startDay, int endDay) {
  int size = 17 + 4 * version;
  int lastTiming = size - 7;
  int lo = startDay > 6 ? startDay : 6;
  int hi = endDay < lastTiming ? endDay : lastTiming;
  if (lo % 2 != 0) lo++;
  if (hi % 2 != 0) hi--;
  List<int> result = [];
  for (int i = lo; i <= hi; i += 2) {
