Map<String, int> trafficLightPhaseTotals(List<List<int>> lightPositions, int centerX, int centerY) {
  int short = 0, medium = 0, longCycle = 0;
  for (final pos in lightPositions) {
    int dist = (pos[0] - centerX).abs() + (pos[1] - centerY).abs();
    if (dist <= 3) {
      short += dist;
    } else if (dist <= 6) {
      medium += dist;
    } else {
      longCycle += dist;
    }
  }
  return {"short": short, "medium": medium, "long": longCycle};
