double averageTrainHeadway(List<int> departureMinutes) {
  if (departureMinutes.length < 2) return 0.0;
  List<int> sorted = List<int>.from(departureMinutes)..sort();
  int totalGap = 0;
  for (int i = 1; i < sorted.length; i++) {
    totalGap += sorted[i] - sorted[i - 1];
  }
  return totalGap / (sorted.length - 1);
}

