  assert(processSensorUndoLog(["A:10", "A:undo"])['A'] == 0);
  assert(processSensorUndoLog(["A:10", "B:20", "A:undo"])['B'] == 20);
  assert(processSensorUndoLog(["A:5", "A:10", "A:undo"])['A'] == 5);
