Set<int> verticalMirrorAxes(List<String> rows) {
  if (rows.isEmpty) return <int>{};
  final int n = rows.length;
  final int w = rows[0].length;
  final Set<int> axes = <int>{};
  for (int c = 0; c < w; c++) {
    bool isMirror = true;
    for (int r = 0; r < n ~/ 2; r++) {
      if (rows[r][c] != rows[n - 1 - r][c]) {
        isMirror = false;
        break;
      }
    }
    if (isMirror) axes.add(c);
  }
  return axes;
}

