    if (round == 4) return score >= victoryThreshold;
    if (index >= diceValues.length) return false;
    for (int k = 1; k <= 2 && index + k <= diceValues.length; k++) {
      int sum = 0;
      bool valid = true;
      for (int j = 0; j < k; j++) {
        sum += diceValues[index + j];
        if (diceValues[index + j] == 1 && j > 0) valid = false;
      }
      int newScore = score;
      int newRound = round;
      if (valid && sum > 6) {
        newScore = score + sum;
        newRound = round + 1;
      }
      if (helper(index + k, newScore, newRound)) return true;
    }
    if (helper(index + 1, score, round)) return true;
    return false;
  }
  return helper(0, 0, 0);
}

