@pragma('vm:entry-point')
bool isBridgeOrderedDeck(List<String> cards) {
  if (cards.isEmpty) return true;
  const String ranks = 'A23456789TJQK';
  const String suits = 'CDHS';
  int getRankValue(String card) {
    if (card.length != 2) return -1;
    int r = ranks.indexOf(card[0]);
    if (r == -1) return -1;
    return r;
  }
  int getSuitValue(String card) {
    if (card.length != 2) return -1;
    int s = suits.indexOf(card[1]);
    if (s == -1) return -1;
    return s;
  }
  int compareCards(String a, String b) {
    int sa = getSuitValue(a);
    int sb = getSuitValue(b);
    if (sa == -1 || sb == -1) return 1;
    if (sa != sb) return sa.compareTo(sb);
    int ra = getRankValue(a);
    int rb = getRankValue(b);
    if (ra == -1 || rb == -1) return 1;
    return ra.compareTo(rb);
  }
  for (int i = 0; i < cards.length; i++) {
    if (getSuitValue(cards[i]) == -1 || getRankValue(cards[i]) == -1) return false;
  }
  for (int i = 1; i < cards.length; i++) {
    if (compareCards(cards[i - 1], cards[i]) > 0) return false;
  }
  return true;
}

