Set<int> decodeElevatorFloorRequests(String encoded) {
  Set<int> floors = {};
  int i = 0;
  while (i < encoded.length) {
    int countStart = i;
    while (i < encoded.length && encoded.codeUnitAt(i) >= 48 && encoded.codeUnitAt(i) <= 57) {
      i++;
    }
    if (i == countStart) {
      i++;
      continue;
    }
    String countStr = encoded.substring(countStart, i);
    int count = int.parse(countStr);
    if (i >= encoded.length) {
      break;
    }
    String letter = encoded[i];
    i++;
    int code = letter.codeUnitAt(0);
    if (code >= 97 && code <= 122) {
      int floor = code - 96;
      if (floor >= 1 && floor <= 26 && count > 0) {
        floors.add(floor);
      }
    }
  }
  return floors;
}

