double calculateSpellSimilarity(String input, String dictionaryWord) {
  int matches = 0;
  int i = 0;
  int j = 0;
  while (i < input.length && j < dictionaryWord.length) {
    if (input[i] == dictionaryWord[j]) {
      matches++;
      i++;
      j++;
    } else if (input.codeUnitAt(i) < dictionaryWord.codeUnitAt(j)) {
      i++;
    } else {
      j++;
    }
  }
  int total = input.length + dictionaryWord.length;
  if (total == 0) return 1.0;
  return 2.0 * matches / total;
}

