Set<int> collectValidPacketAcknowledgements(List<int> arrivals) {
  var stack = <int>[];
  var valid = <int>{};
  for (var size in arrivals) {
    if (size > 0) {
      stack.add(size);
    } else if (size < 0) {
      if (stack.isNotEmpty) {
        var last = stack.removeLast();
        if (last == -size) {
          valid.add(last);
        } else {
          stack.add(last);
        }
      }
    }
  }
  return valid;
}

