@pragma('vm:entry-point')
List<int> findActivePhases(List<int> phaseDurations, List<int> queryTimes) {
  // A traffic light cycles through phases with the given durations (seconds).
  // For each query time (seconds since the cycle started), return the index
  // of the active phase, using binary search over cumulative phase end times.
  List<int> result = [];
  if (phaseDurations.isEmpty) {
    return List<int>.filled(queryTimes.length, -1);
  }
  List<int> prefix = [];
  int total = 0;
  for (int d in phaseDurations) {
    total += d;
    prefix.add(total);
  }
  for (int t in queryTimes) {
    int m = t % total;
    int lo = 0;
    int hi = prefix.length - 1;
    while (lo < hi) {
      int mid = (lo + hi) ~/ 2;
      if (prefix[mid] > m) {
        hi = mid;
      } else {
        lo = mid + 1;
      }
    }
    result.add(lo);
  }
  return result;
}

