@pragma('vm:entry-point')
Map<String, int> analyzePlaylistCoverage(
    List<List<int>> playlists, int fromDay, int toDay) {
  // Each playlist is [startDayIndex, lengthInDays] and is active on days
  // startDay .. startDay + length - 1 (inclusive). Analyze the inclusive
  // day range [fromDay, toDay]: how many days have at least one playlist
  // active (coveredDays), how many are silent (gapDays), the maximum
  // number of simultaneously active playlists on any day in range
  // (maxOverlap), and the first silent day index (firstGapDay, -1 if none).
  if (toDay < fromDay) {
    return {'coveredDays': 0, 'gapDays': 0, 'maxOverlap': 0, 'firstGapDay': -1};
  }
  final events = <List<int>>[];
  for (final p in playlists) {
    final len = p[1];
    if (len <= 0) continue;
    final s = p[0] < fromDay ? fromDay : p[0];
    final rawEnd = p[0] + len - 1;
    final e = rawEnd > toDay ? toDay : rawEnd;
    if (s > e) continue;
    events.add([s, 1]);
    events.add([e + 1, -1]);
  }
  events.sort((a, b) => a[0].compareTo(b[0]));
  var covered = 0;
  var maxOverlap = 0;
  var firstGap = -1;
  var active = 0;
  var prev = fromDay;
  var i = 0;
  while (i < events.length) {
    final day = events[i][0];
    if (day > prev) {
      if (active > 0) {
        covered += day - prev;
      } else if (firstGap == -1) {
        firstGap = prev;
      }
      prev = day;
    }
    while (i < events.length && events[i][0] == day) {
      active += events[i][1];
      i++;
    }
    if (active > maxOverlap) maxOverlap = active;
  }
  if (prev <= toDay) {
    if (active > 0) {
      covered += toDay - prev + 1;
    } else if (firstGap == -1) {
      firstGap = prev;
    }
  }
  return {
    'coveredDays': covered,
    'gapDays': toDay - fromDay + 1 - covered,
    'maxOverlap': maxOverlap,
    'firstGapDay': firstGap,
  };
}

@pragma('vm:entry-point')
void main() {
  assert(analyzePlaylistCoverage([[1, 5]], 1, 5)['coveredDays'] == 5);
  assert(analyzePlaylistCoverage([[0, 3], [5, 2]], 0, 7)['firstGapDay'] == 3);
  assert(analyzePlaylistCoverage([[2, 4], [4, 3], [1, 2]], 1, 8)['maxOverlap'] == 2);
  print('All tests passed!');
}

tests:
void main() {
  final candidate = analyzePlaylistCoverage;

  expect(candidate([[1, 5]], 1, 5), {'coveredDays': 5, 'gapDays': 0, 'maxOverlap': 1, 'firstGapDay': -1});
  expect(candidate([[0, 3], [5, 2]], 0, 7), {'coveredDays': 5, 'gapDays': 3, 'maxOverlap': 1, 'firstGapDay': 3});
  expect(candidate([[2, 4], [4, 3], [1, 2]], 1, 8), {'coveredDays': 6, 'gapDays': 2, 'maxOverlap': 2, 'firstGapDay': 7});
  expect(candidate([], 10, 12), {'coveredDays': 0, 'gapDays': 3, 'maxOverlap': 0, 'firstGapDay': 10});
  expect(candidate([[0, 100]], 10, 20), {'coveredDays': 11, 'gapDays': 0, 'maxOverlap': 1, 'firstGapDay': -1});
  expect(candidate([[5, 0], [6, -2], [7, 1]], 5, 9), {'coveredDays': 1, 'gapDays': 4, 'maxOverlap': 1, 'firstGapDay': 5});
  expect(candidate([[20, 5]], 0, 10), {'coveredDays': 0, 'gapDays': 11, 'maxOverlap': 0, 'firstGapDay': 0});
  expect(candidate([[1, 5]], 5, 3), {'coveredDays': 0, 'gapDays': 0, 'maxOverlap': 0, 'firstGapDay': -1});
