  assert(arePixelsCanonicallyOrdered([[0, 0, 0], [255, 0, 0], [0, 255, 0]]) == true);
  assert(arePixelsCanonicallyOrdered([[0, 255, 0], [255, 0, 0]]) == false);
  assert(arePixelsCanonicallyOrdered([]) == true);
