double mazePrimeTokenValue(int rows, int cols) {
  // Maze cells are numbered 1..rows*cols in row-major order.
  // Every cell whose number is prime holds a token worth 0.25.
  int total = rows * cols;
  double value = 0.0;
  for (int n = 2; n <= total; n++) {
    bool isPrime = true;
    for (int d = 2; d * d <= n; d++) {
      if (n % d == 0) {
        isPrime = false;
        break;
      }
    }
    if (isPrime) value += 0.25;
  }
  return value;
}

@pragma('vm:entry-point')
void main() {
