@pragma('vm:entry-point')
String rotatePlaylistLikes(int likedMask, int trackCount, int rotation) {
  // A playlist has trackCount tracks; bit i of likedMask means track i is liked.
  // Rotating the playlist by `rotation` moves every track i to (i + rotation) mod trackCount.
  // Returns a visual strip ('#' = liked, '-' = not) plus the liked count.
  if (trackCount <= 0) return 'liked=0 []';
  final int fieldMask = (1 << trackCount) - 1;
  final int bits = likedMask & fieldMask;
  final int r = ((rotation % trackCount) + trackCount) % trackCount;
  final int rotated = ((bits << r) | (bits >> (trackCount - r))) & fieldMask;
  int count = 0;
  final StringBuffer strip = StringBuffer();
  for (int i = 0; i < trackCount; i++) {
    if (((rotated >> i) & 1) == 1) {
      strip.write('#');
      count++;
    } else {
      strip.write('-');
    }
  }
  return 'liked=$count [${strip.toString()}]';
}

@pragma('vm:entry-point')
void main() {
  assert(rotatePlaylistLikes(11, 4, 1) == 'liked=3 [###-]');
  assert(rotatePlaylistLikes(5, 4, 0) == 'liked=2 [#-#-]');
  assert(rotatePlaylistLikes(0, 5, 3) == 'liked=0 [-----]');
  print('All tests passed!');
}

