@pragma('vm:entry-point')
Map<String, int> analyzeDiceTournament(List<int> roundDays, int cooldown) {
  // Each entry in roundDays is the day index a dice round was scheduled.
  // A round is actually PLAYED only if more than `cooldown` days have
  // passed since the previously played round; otherwise it is forfeited.
  // Days may arrive unsorted and may contain duplicates.
  final days = List<int>.from(roundDays)..sort();
  var played = 0;
  var forfeited = 0;
  var longestGap = 0;
  var firstPlayed = 0;
  var lastPlayed = 0;
  var hasPlayed = false;
  for (final d in days) {
    if (!hasPlayed) {
      hasPlayed = true;
      played = 1;
      firstPlayed = d;
      lastPlayed = d;
    } else if (d - lastPlayed > cooldown) {
      final gap = d - lastPlayed;
      if (gap > longestGap) longestGap = gap;
      played++;
      lastPlayed = d;
    } else {
      forfeited++;
    }
  }
  final span = hasPlayed ? lastPlayed - firstPlayed : 0;
  final restDays = played > 1 ? span - (played - 1) : 0;
  return {
    'played': played,
    'forfeited': forfeited,
    'span': span,
    'longestGap': longestGap,
    'restDays': restDays,
  };
}

@pragma('vm:entry-point')
void main() {
  assert(analyzeDiceTournament([1, 3, 4, 8, 9, 15], 2)['played'] == 4);
  assert(analyzeDiceTournament([5, 6, 7, 8], 3)['forfeited'] == 3);
  assert(analyzeDiceTournament([], 1)['span'] == 0);
  print('All tests passed!');
}

