double shelfCodeCoverageArea(List<int> shelfXs, List<int> shelfYs) {
  if (shelfXs.isEmpty || shelfYs.isEmpty) {
    return 0.0;
  }
  int minX = shelfXs[0];
  int maxX = shelfXs[0];
  int minY = shelfYs[0];
  int maxY = shelfYs[0];
  for (int i = 1; i < shelfXs.length; i++) {
    if (shelfXs[i] < minX) minX = shelfXs[i];
    if (shelfXs[i] > maxX) maxX = shelfXs[i];
    if (shelfYs[i] < minY) minY = shelfYs[i];
    if (shelfYs[i] > maxY) maxY = shelfYs[i];
  }
  return ((maxX - minX) * (maxY - minY)).toDouble();
}

@pragma('vm:entry-point')
void main() {
  assert(shelfCodeCoverageArea([1, 4, 2], [2, 6, 3]) == 12.0);
  assert(shelfCodeCoverageArea([5], [9]) == 0.0);
  assert(shelfCodeCoverageArea([], []) == 0.0);
  print('All tests passed!');
}

