List<int> sortTidesByLowWater(List<int> readings, int lowWaterLevel) {
  List<int> sorted = List<int>.from(readings);
  sorted.sort((a, b) {
    int diffA = (a - lowWaterLevel).abs();
    int diffB = (b - lowWaterLevel).abs();
    if (diffA != diffB) {
