String countUniqueSquareColors(List<String> squares) {
  Set<String> seen = {};
  int light = 0;
  int dark = 0;
  for (String square in squares) {
    if (square.length != 2 || seen.contains(square)) {
      continue;
    }
    seen.add(square);
    int file = square.codeUnitAt(0) - 96;
    int rank = int.parse(square[1]);
    if ((file + rank) % 2 == 0) {
      dark++;
    } else {
      light++;
    }
  }
  return 'light:$light,dark:$dark';
}

