  assert(decodePlaylistFlags([0], ['LoFi', 'Drum'], 0).toString() == '[LoFi|sync&day|0]');
  assert(decodePlaylistFlags([1], ['LoFi', 'Drum', 'Synth'], 0).toString() == '[Drum|solo&day|2]');
  assert(decodePlaylistFlags([], ['LoFi'], 5).length == 0);
  print('All tests passed!');
