@pragma('vm:entry-point')
int minimumManifestWaste(List<int> crateWeights, int maxItemsPerManifest) {
  int n = crateWeights.length;
  if (n == 0) {
    return 0;
  }

  List<int> dp = List<int>.filled(n + 1, 1 << 30);
  dp[0] = 0;

  for (int i = 1; i <= n; i++) {
    int currentMax = 0;
    int currentSum = 0;

    for (int size = 1; size <= maxItemsPerManifest && size <= i; size++) {
      int weight = crateWeights[i - size];
      if (weight > currentMax) {
        currentMax = weight;
      }

      currentSum += weight;
      int capacity = currentMax * size;
      int waste = capacity - currentSum;

      int candidate = dp[i - size] + waste;
      if (candidate < dp[i]) {
        dp[i] = candidate;
      }
    }
  }

  return dp[n];
}

