@pragma('vm:entry-point')
String orderedServerLogs(List<String> logs) {
  List<String> sorted = List<String>.from(logs);
  Map<String, int> priority = {
    'ERROR': 0,
    'WARN': 1,
    'INFO': 2,
  };
  sorted.sort((a, b) {
    String levelA = a.split(' ')[0];
    String levelB = b.split(' ')[0];
    int diff = priority[levelA]!.compareTo(priority[levelB]!);
    return diff != 0 ? diff : a.compareTo(b);
  });
  return sorted.join('|');
}

