  expect(candidate('UX|3D1', 0).toString(), '{finalFloor: -3, served: 3, checksum: 0, invalid: 1}');
  expect(candidate('U2|2D1', 0).toString(), '{finalFloor: 0, served: 3, checksum: 2979, invalid: 0}');
