Map<String, int> tallyPlaylistTracks(String script) {
  Map<String, int> result = {};
  int i = 0;

  while (i < script.length) {
    while (i < script.length && (script[i] == ' ' || script[i] == ';')) {
      i++;
    }
    if (i >= script.length || script[i] != '[') {
      break;
    }

    int endName = script.indexOf(']', i);
    if (endName == -1) {
      break;
    }

    String name = script.substring(i + 1, endName).trim();
    i = endName + 1;

    while (i < script.length && script[i] == ' ') {
      i++;
    }
    if (i >= script.length || script[i] != ':') {
      break;
    }
    i++;

    int total = result[name] ?? 0;
    StringBuffer token = StringBuffer();
    bool inQuotes = false;
    bool escaping = false;

    while (i <= script.length) {
      String ch = i < script.length ? script[i] : ';';

      if (escaping) {
        token.write(ch);
        escaping = false;
      } else if (inQuotes && ch == '\\') {
        escaping = true;
      } else if (ch == '"') {
        inQuotes = !inQuotes;
      } else if (!inQuotes && (ch == ',' || ch == ';')) {
        String part = token.toString().trim();
        if (part.isNotEmpty) {
          int count = 1;
          int star = part.lastIndexOf('*');
          if (star > 0) {
            String repeat = part.substring(star + 1).trim();
            if (repeat.isNotEmpty) {
              int? parsed = int.tryParse(repeat);
              if (parsed != null && parsed > 0) {
                count = parsed;
              }
            }
          }
          total += count;
        }

        token.clear();
        if (ch == ';') {
          i++;
          break;
        }
      } else {
        token.write(ch);
      }

      i++;
    }

    result[name] = total;
  }

  return result;
}

