void main() {
  assert(warehouseLayerAudit([[1, 0, 2], [3, 4, 0], [5, 6, 7]]).toString() == '[93, 4]');
  assert(warehouseLayerAudit([[1, 0, 2, 3]]).toString() == '[11]');
  assert(warehouseLayerAudit([[0, 0], [0, 0]]).toString() == '[0]');
  print('All tests passed!');
}

