@pragma('vm:entry-point')
Map<String, int> scoreDiceRoundGrid(List<int> xs, List<int> ys, int targetX, int targetY) {
  if (xs.isEmpty || ys.isEmpty || xs.length != ys.length) {
    return {'distance': 0, 'area': 0};
  }
  int minX = xs[0], maxX = xs[0];
  int minY = ys[0], maxY = ys[0];
  int distance = 0;
  for (int i = 0; i < xs.length; i++) {
    distance += (xs[i] - targetX).abs() + (ys[i] - targetY).abs();
    if (xs[i] < minX) minX = xs[i];
    if (xs[i] > maxX) maxX = xs[i];
    if (ys[i] < minY) minY = ys[i];
    if (ys[i] > maxY) maxY = ys[i];
  }
  return {'distance': distance, 'area': (maxX - minX) * (maxY - minY)};
}

