  assert(scoreDiceRoundGrid([1, 3], [2, 4], 0, 0).toString() == '{distance: 10, area: 4}');
  assert(scoreDiceRoundGrid([5], [5], 5, 5).toString() == '{distance: 0, area: 0}');
