List<int> reconcileTelemetrySamples(List<String> operations) {
  List<int> samples = [];
  for (String op in operations) {
    if (op == 'UNDO') {
      if (samples.isNotEmpty) {
        samples.removeLast();
      }
    } else {
      List<String> parts = op.split(' ');
      samples.add(int.parse(parts[1]));
    }
  }
  return samples;
}

