@pragma('vm:entry-point')
bool hasUniqueDominantErrorMessages(List<String> logs) {
  Map<String, Map<String, int>> messageCounts = {};
  Map<String, int> errorTotals = {};

  for (String line in logs) {
    List<String> parts = line.split('|');
    if (parts.length != 3) {
      return false;
    }

    String server = parts[0];
    String level = parts[1];
    String message = parts[2];

    if (level != 'ERROR') {
      continue;
    }

    errorTotals[server] = (errorTotals[server] ?? 0) + 1;
    messageCounts.putIfAbsent(server, () => {});
    messageCounts[server]![message] =
        (messageCounts[server]![message] ?? 0) + 1;
  }

  if (errorTotals.isEmpty) {
    return false;
  }

  Set<String> dominantMessages = {};

  for (String server in errorTotals.keys) {
    int total = errorTotals[server]!;
    String dominant = '';
    int maxCount = 0;

    for (String message in messageCounts[server]!.keys) {
      int count = messageCounts[server]![message]!;
      if (count > maxCount) {
        maxCount = count;
        dominant = message;
      }
    }

    if (maxCount * 2 <= total) {
      return false;
    }

    if (dominantMessages.contains(dominant)) {
      return false;
    }

    dominantMessages.add(dominant);
  }

  return true;
}

@pragma('vm:entry-point')
void main() {
  assert(hasUniqueDominantErrorMessages(["api|ERROR|timeout","api|ERROR|timeout","db|ERROR|disk"]) == true);
  assert(hasUniqueDominantErrorMessages(["api|ERROR|x","api|ERROR|y"]) == false);
  assert(hasUniqueDominantErrorMessages(["web|INFO|ok"]) == false);
  print('All tests passed!');
}

tests:
void main() {
  final candidate = hasUniqueDominantErrorMessages;

  expect(candidate(["a|ERROR|timeout","a|ERROR|timeout","a|INFO|ok","b|ERROR|disk","b|ERROR|disk","b|ERROR|cpu","b|ERROR|disk"]), true);
  expect(candidate(["a|ERROR|x","a|ERROR|y"]), false);
  expect(candidate(["a|ERROR|x","a|ERROR|x","b|ERROR|x"]), false);
  expect(candidate(["badline"]), false);
  expect(candidate(["srv|INFO|ok","srv|WARN|slow"]), false);
  expect(candidate(["solo|ERROR|memory"]), true);
  expect(candidate([]), false);
  expect(candidate(["a|ERROR|m1","a|ERROR|m1","a|ERROR|m2","b|ERROR|m3","b|ERROR|m3"]), true);
}

