@pragma('vm:entry-point')
Set<int> primeShelfCodeGroups(List<int> shelfCodes, int base) {
  if (base < 2) {
    return <int>{};
  }

  bool isPrime(int value) {
    if (value < 2) {
      return false;
    }
    for (int i = 2; i * i <= value; i++) {
      if (value % i == 0) {
        return false;
      }
    }
    return true;
  }

  int gcd(int a, int b) {
    while (b != 0) {
      int temp = a % b;
      a = b;
      b = temp;
    }
    return a.abs();
  }

  Set<int> groups = <int>{};

  for (int code in shelfCodes) {
    if (code <= 0) {
      continue;
    }

    int n = code;
    int digitSum = 0;
    List<int> digits = <int>[];

    while (n > 0) {
      int digit = n % base;
      digits.add(digit);
      digitSum += digit;
      n ~/= base;
    }

    if (!isPrime(digitSum)) {
      continue;
    }

    int reversedValue = 0;
    for (int digit in digits) {
      reversedValue = reversedValue * base + digit;
    }

    int sharedFactor = gcd(code, reversedValue);
    if (sharedFactor > 1) {
      groups.add(sharedFactor + digitSum);
    }
  }

  return groups;
}

@pragma('vm:entry-point')
void main() {
  assert(primeShelfCodeGroups([10], 2).length == 1);
  assert(primeShelfCodeGroups([12, 21], 10).toString() == '{6}');
  assert(primeShelfCodeGroups([5, 7], 1).isEmpty);
  print('All tests passed!');
}

tests:
void main() {
  final candidate = primeShelfCodeGroups;

  expect(candidate([], 2).toString(), '{}');
  expect(candidate([10], 2).toString(), '{7}');
  expect(candidate([12, 21], 10).toString(), '{6}');
  expect(candidate([5, 7], 1).toString(), '{}');
  expect(candidate([-5, 0, 10], 2).toString(), '{7}');
  expect(candidate([11], 2).toString(), '{}');
  expect(candidate([18, 9, 10], 2).toString(), '{11, 7}');
  expect(candidate([28], 3).toString(), '{30}');
}

