  final candidate = playlistFlagEntropy;

  expect(candidate([], 0), 0);
  expect(candidate([1], 0), 3);
  expect(candidate([2], 0), 3);
  expect(candidate([3], 0), 6);
  expect(candidate([1, 2], 0), 2);
  expect(candidate([1, 2], 1), 2);
  expect(candidate([7, 7], 0), 12);
}

