@pragma('vm:entry-point')
List<String> kthSafeChessSquares(int boardSize, List<String> queens, List<int> queries) {
  List<List<int>> queenPos = [];
  for (String q in queens) {
    int col = q.codeUnitAt(0) - 97;
    int row = int.parse(q.substring(1)) - 1;
    queenPos.add([row, col]);
  }

  List<List<int>> safeColsByRow = List.generate(boardSize, (_) => []);
  List<int> prefix = List.filled(boardSize + 1, 0);

  for (int r = 0; r < boardSize; r++) {
    for (int c = 0; c < boardSize; c++) {
      bool safe = true;
      for (List<int> q in queenPos) {
        int qr = q[0];
        int qc = q[1];
        if (r == qr || c == qc || (r - qr).abs() == (c - qc).abs()) {
          safe = false;
          break;
        }
      }
      if (safe) {
        safeColsByRow[r].add(c);
      }
    }
    prefix[r + 1] = prefix[r] + safeColsByRow[r].length;
  }

  List<String> result = [];
  for (int k in queries) {
    if (k <= 0 || k > prefix[boardSize]) {
      result.add("");
      continue;
    }

    int left = 0;
    int right = boardSize - 1;
    while (left < right) {
      int mid = (left + right) ~/ 2;
      if (prefix[mid + 1] >= k) {
        right = mid;
      } else {
        left = mid + 1;
      }
    }

    int row = left;
    int offset = k - prefix[row] - 1;
    int col = safeColsByRow[row][offset];
    result.add('${String.fromCharCode(97 + col)}${row + 1}');
  }

  return result;
}

@pragma('vm:entry-point')
void main() {
  assert(kthSafeChessSquares(4, [], [16])[0] == 'd4');
  assert(kthSafeChessSquares(4, ['b2'], [6])[0] == '');
  assert(kthSafeChessSquares(3, ['a1'], [1, 2]).length == 2);
  print('All tests passed!');
}

tests:
void main() {
  final candidate = kthSafeChessSquares;

  expect(candidate(4, [], [1, 6, 16, 17]).toString(), '[a1, b2, d4, ]');
  expect(candidate(1, [], [1, 2]).toString(), '[a1, ]');
  expect(candidate(1, ['a1'], [1]).toString(), '[]');
  expect(candidate(3, ['b2'], [1]).toString(), '[]');
  expect(candidate(6, [], [7, 18, 36]).toString(), '[a2, f3, f6]');
}

